const input = $('Workflow Input').first().json;
let incoming = [];
try { incoming = JSON.parse(input.slots_json || '[]'); } catch (e) { incoming = []; }
if (!Array.isArray(incoming)) incoming = [];

const rows = $input.all().map(function (i) { return i.json; });
const defs = {};
for (const r of rows) { defs[r.slot_key] = r; }

const marketCurrency = ((rows[0] && rows[0].market_currency) || 'AED').toUpperCase();
const fxRates = (rows[0] && rows[0].fx_rates) || {};
const leadFullName = String((rows[0] && rows[0].lead_full_name) || '').trim();

// A lead may quote any currency. Normalise to the market currency before anything
// downstream compares it against a threshold or searches listings with it. What they
// actually said is kept under `original` so the brief can quote them.
function normaliseMoney(v) {
  if (!v || typeof v !== 'object' || Array.isArray(v)) return v;
  const raw = (typeof v.currency === 'string' && v.currency) ? v.currency.toUpperCase() : marketCurrency;
  if (raw === marketCurrency) {
    const same = Object.assign({}, v);
    same.currency = marketCurrency;
    return same;
  }
  const rate = Number(fxRates[raw]);
  if (!isFinite(rate) || rate <= 0) {
    const unknown = Object.assign({}, v);
    unknown.currency = raw;
    unknown.fx_applied = false;
    return unknown;
  }
  const conv = { currency: marketCurrency, fx_applied: true, original: { currency: raw } };
  if (typeof v.min === 'number') { conv.min = Math.round(v.min * rate); conv.original.min = v.min; }
  if (typeof v.max === 'number') { conv.max = Math.round(v.max * rate); conv.original.max = v.max; }
  return conv;
}

function materiallyDifferent(type, oldV, newV) {
  if (oldV === null || oldV === undefined) return false;
  if (type === 'currency_range') {
    const a = (oldV && typeof oldV === 'object') ? oldV : {};
    const b = (newV && typeof newV === 'object') ? newV : {};
    const aMin = typeof a.min === 'number' ? a.min : 0;
    const aMax = typeof a.max === 'number' ? a.max : Number.MAX_SAFE_INTEGER;
    const bMin = typeof b.min === 'number' ? b.min : 0;
    const bMax = typeof b.max === 'number' ? b.max : Number.MAX_SAFE_INTEGER;
    return !(aMin <= bMax && bMin <= aMax);
  }
  if (type === 'contact') return false;
  if (type === 'number') return Number(oldV) !== Number(newV);
  if (type === 'enum' || type === 'text' || type === 'date') return String(oldV) !== String(newV);
  return JSON.stringify(oldV) !== JSON.stringify(newV);
}

function mergeContact(oldV, newV) {
  const o = (oldV && typeof oldV === 'object' && !Array.isArray(oldV)) ? oldV : {};
  const n = (newV && typeof newV === 'object' && !Array.isArray(newV)) ? newV : {};
  const merged = Object.assign({}, o);
  const keys = ['full_name', 'phone', 'email'];
  for (const k of keys) {
    if (typeof n[k] === 'string' && n[k].trim().length > 0) merged[k] = n[k].trim();
  }
  // The bot no longer asks for a name the channel already gave us, so the lead
  // will often send back a bare number. Fall back to the display name.
  if (!merged.full_name && leadFullName) merged.full_name = leadFullName;
  return merged;
}

const plan = [];
for (const s of incoming) {
  if (!s || typeof s.slot_key !== 'string') continue;
  const def = defs[s.slot_key];
  if (!def) continue;
  const type = def.value_type;
  let value = s.value;
  let state = 'filled';
  const prev = Array.isArray(def.previous_values) ? def.previous_values.slice() : [];

  if (type === 'currency_range') {
    value = normaliseMoney(value);
  }

  if (type === 'contact') {
    value = mergeContact(def.current_value, value);
  } else if (def.current_state === 'filled' && def.current_value !== null && def.current_value !== undefined) {
    if (materiallyDifferent(type, def.current_value, value)) {
      prev.push(def.current_value);
      state = 'conflicted';
    }
  }
  plan.push({ slot_key: s.slot_key, value: value, state: state, previous_values: prev });
}

return [{ json: { conversation_id: input.conversation_id, plan_json: JSON.stringify(plan) } }];
